-- Phase 22 — bulletins figés et publiables
CREATE TYPE "report_card_status" AS ENUM ('DRAFT', 'PUBLISHED');
CREATE TABLE "report_cards" ("id" UUID NOT NULL DEFAULT uuidv7(), "school_id" UUID NOT NULL, "academic_year_id" UUID NOT NULL, "period_id" UUID NOT NULL, "enrollment_id" UUID NOT NULL, "overall_average" INTEGER, "rank" INTEGER, "general_comment" TEXT, "decision" TEXT, "status" "report_card_status" NOT NULL DEFAULT 'DRAFT', "snapshot" JSONB, "published_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "report_cards_pkey" PRIMARY KEY ("id"), CONSTRAINT "report_cards_values_valid" CHECK ((overall_average IS NULL OR overall_average BETWEEN 0 AND 2000) AND (rank IS NULL OR rank > 0)), CONSTRAINT "report_cards_school_id_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE CASCADE, CONSTRAINT "report_cards_academic_year_id_fkey" FOREIGN KEY ("academic_year_id") REFERENCES "academic_years"("id") ON DELETE CASCADE, CONSTRAINT "report_cards_period_id_fkey" FOREIGN KEY ("period_id") REFERENCES "academic_periods"("id") ON DELETE RESTRICT, CONSTRAINT "report_cards_enrollment_id_fkey" FOREIGN KEY ("enrollment_id") REFERENCES "enrollments"("id") ON DELETE RESTRICT);
CREATE TABLE "report_card_subjects" ("report_card_id" UUID NOT NULL, "subject_id" UUID NOT NULL, "subject_name" TEXT NOT NULL, "average" INTEGER, "coefficient" INTEGER NOT NULL DEFAULT 100, "teacher_comment" TEXT, CONSTRAINT "report_card_subjects_pkey" PRIMARY KEY ("report_card_id", "subject_id"), CONSTRAINT "report_card_subjects_values_valid" CHECK ((average IS NULL OR average BETWEEN 0 AND 2000) AND coefficient > 0), CONSTRAINT "report_card_subjects_report_card_id_fkey" FOREIGN KEY ("report_card_id") REFERENCES "report_cards"("id") ON DELETE CASCADE, CONSTRAINT "report_card_subjects_subject_id_fkey" FOREIGN KEY ("subject_id") REFERENCES "subjects"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "report_cards_enrollment_id_period_id_key" ON "report_cards"("enrollment_id", "period_id"); CREATE INDEX "report_cards_school_id_academic_year_id_period_id_status_idx" ON "report_cards"("school_id", "academic_year_id", "period_id", "status"); CREATE INDEX "report_card_subjects_subject_id_idx" ON "report_card_subjects"("subject_id");
CREATE TRIGGER trg_report_cards_updated_at BEFORE UPDATE ON "report_cards" FOR EACH ROW EXECUTE FUNCTION set_updated_at(); ALTER TABLE "report_cards" ENABLE ROW LEVEL SECURITY; CREATE POLICY school_isolation ON "report_cards" USING (current_school_id() IS NULL OR school_id = current_school_id()) WITH CHECK (current_school_id() IS NULL OR school_id = current_school_id());
